use serde_json::{json,Value};
use sha2::{Digest,Sha256};
use std::{collections::BTreeMap,fs,io::Read,path::Path};
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn hash(p:impl AsRef<Path>)->String{let mut f=fs::File::open(p).unwrap();let mut h=Sha256::new();let mut b=[0;65536];loop{let n=f.read(&mut b).unwrap();if n==0{break}h.update(&b[..n]);}format!("{:x}",h.finalize())}
fn add(p:impl AsRef<Path>,pins:&mut BTreeMap<String,String>){let p=p.as_ref();pins.insert(p.to_str().unwrap().into(),hash(p));}
fn main(){let root=Path::new("/tmp/zopro-front-snapshot-fence");let old=fs::read_to_string("/tmp/zopro-serial-fft-leaves/native-plan-v2.json").unwrap();let text=old.replace("/tmp/zopro-serial-fft-leaves/candidate-v2","/tmp/zopro-front-snapshot-fence/candidate").replace("/tmp/zopro-serial-fft-leaves/target-native-v2","/tmp/zopro-front-snapshot-fence/target-native").replace("/tmp/zopro-serial-fft-leaves/native-v2","/tmp/zopro-front-snapshot-fence/native").replace("zopro_serial_fft_leaves","zopro_front_snapshot_fence").replace("ZOPRO_CPU_SERIAL_FFT_LEAVES","ZOPRO_CPU_FRONT_SNAPSHOT_FENCE");let mut plan:Value=serde_json::from_str(&text).unwrap();plan["source_pins"]=json!(root.join("build-input-pins.json"));for step in plan["steps"].as_array_mut().unwrap(){if step["name"]=="core-off"||step["name"]=="core-on"{step.as_object_mut().unwrap().remove("required_tests");}}
let mut steps=vec![plan["steps"][0].clone()];steps.push(json!({"kind":"command","name":"ordering-model","argv":["cargo","test","--offline","--locked","--release","--manifest-path",root.join("model/Cargo.toml"),"--lib","--","--test-threads=1"],"environment":{"RUSTFLAGS":"","CARGO_TARGET_DIR":root.join("model/target")},"timeout_seconds":1200,"unfiltered":true,"required_tests":["common_fence_preserves_both_store_buffering_pairs","missing_common_fence_negative_control_detects_forbidden_pair","common_fence_two_thieves_and_owner_last_pop_are_unique","release_publication_is_visible_after_saved_front_and_back_acquire","generation_publication_and_two_snapshot_readers_preserve_tasks"]}));
let required=json!(["deque::front_snapshot_tests::tile_bounds_order_mixed_flavors_and_duplicate_references","deque::front_snapshot_tests::stale_front_retry_is_aggregated_and_later_success_wins","deque::front_snapshot_tests::guards_drop_on_empty_success_and_nested_calls","deque::front_snapshot_tests::owner_drop_and_pending_payload_destruction_remain_exactly_once","deque::front_snapshot_tests::concurrent_multiqueue_growth_owner_pop_and_tiles_are_exactly_once","deque::front_snapshot_tests::ordinary_retired_arrays_reclaim_after_snapshot_guards_drop"]);
for mode in ["off","on"]{for(name,path,tests)in [("deque","vendor/crossbeam-deque-0.8.8/Cargo.toml",required.clone()),("rayon","vendor/rayon-core-1.13.0/Cargo.toml",json!(["registry::front_snapshot::tests::registry_samples_explicit_mode_before_worker_execution","nested_bursts_fifo_reuse_and_pool_drop_are_exactly_once","cross_pool_entry_panic_cleanup_and_reuse_complete"]))]{steps.push(json!({"kind":"command","name":format!("{name}-{mode}"),"argv":["cargo","test","--manifest-path",root.join("candidate").join(path),"--offline","--locked","--release","--lib","--tests","--","--test-threads=1"],"environment":{"ZOPRO_CPU_FRONT_SNAPSHOT_FENCE":if mode=="on"{"1"}else{"0"},"CARGO_TARGET_DIR":root.join("target-upstream")},"timeout_seconds":1200,"unfiltered":true,"required_tests":tests}));}}
steps.extend(plan["steps"].as_array().unwrap().iter().skip(1).cloned());plan["steps"]=json!(steps);
let mut pins:BTreeMap<String,String>=serde_json::from_value(read(root.join("candidate/.xtask/source-pins.json"))).unwrap();for name in ["model/Cargo.toml","model/Cargo.lock","model/src/lib.rs","model-tests.log","experiment.json","implement.rs","prepare-build.rs","prepare.json","upstream-deque.rs","upstream-registry.rs","upstream-pins.json","lock-audit.json","source-audit.rs","source-audit.json","ordering-review.md"]{add(root.join(name),&mut pins)}for(p,h)in read(root.join("upstream-pins.json")).as_object().unwrap(){assert_eq!(hash(p),h.as_str().unwrap());pins.insert(p.into(),h.as_str().unwrap().into());}add("/home/ubuntu/src/zk-tools/zopro/xtask/target/release/xtask",&mut pins);fs::write(root.join("build-input-pins.json"),serde_json::to_vec_pretty(&pins).unwrap()).unwrap();fs::write(root.join("native-plan.json"),serde_json::to_vec_pretty(&plan).unwrap()).unwrap();println!("FROZEN native build/test protocol{} inputs",pins.len());}
